import Foundation
import Testing

@testable import NoteCraftCore

// The pretrained network reads pictures that `SymbolRaster` makes. The training script makes its
// pictures with its own copy of the same algorithm; if the two drift apart the network reads
// something it was never taught, and nothing else would notice.
private let golden: [String: ([[Point]], String)] = [
  "seven": ([[Point(0.0, 0.02), Point(0.25, 0.02), Point(0.5, 0.02)], [Point(0.5, 0.02), Point(0.32, 0.5), Point(0.14, 1.0)]],
    ""),
  "ring": ([[Point(0.54, 0.5), Point(0.5334812571672742, 0.6112604669781572), Point(0.514251905654629, 0.716941869558779), Point(0.4832761854416878, 0.8117449009293667), Point(0.44210734848327077, 0.890915741234015), Point(0.3928097721705652, 0.9504844339512095), Point(0.33785544282864177, 0.9874639560909118), Point(0.28, 1.0), Point(0.22214455717135828, 0.9874639560909118), Point(0.16719022782943493, 0.9504844339512095), Point(0.11789265151672931, 0.890915741234015), Point(0.07672381455831229, 0.8117449009293668), Point(0.04574809434537108, 0.7169418695587791), Point(0.026518742832725872, 0.6112604669781573), Point(0.020000000000000018, 0.5000000000000001), Point(0.026518742832725872, 0.38873953302184283), Point(0.045748094345371054, 0.28305813044122097), Point(0.07672381455831223, 0.1882550990706333), Point(0.11789265151672929, 0.10908425876598515), Point(0.16719022782943488, 0.04951556604879048), Point(0.22214455717135823, 0.01253604390908819), Point(0.27999999999999997, 0.0), Point(0.3378554428286417, 0.01253604390908819), Point(0.3928097721705651, 0.04951556604879037), Point(0.4421073484832707, 0.10908425876598504), Point(0.48327618544168777, 0.18825509907063315), Point(0.514251905654629, 0.28305813044122086), Point(0.5334812571672741, 0.38873953302184266), Point(0.54, 0.4999999999999999)]],
    ""),
  "plus": ([[Point(0, 0.5), Point(0.25, 0.5), Point(0.5, 0.5)], [Point(0.25, 0.25), Point(0.25, 0.5), Point(0.25, 0.75)]],
    ""),
  "dot_bar": ([[Point(0, 0.5), Point(0.5, 0.5)], [Point(0.25, 0.27), Point(0.255, 0.275)], [Point(0.25, 0.73), Point(0.255, 0.735)]],
    ""),
]

@Suite struct SymbolNetTests {
  @Test(arguments: ["seven", "ring", "plus", "dot_bar"])
  func theRasterIsTheOneTheNetworkWasTrainedOn(_ name: String) throws {
    let (strokes, expected) = try #require(golden[name])
    let picture = try #require(SymbolRaster.render(strokes))
    #expect(picture.count == 28 * 28)
    var worst = 0
    for i in 0..<picture.count {
      let start = expected.index(expected.startIndex, offsetBy: 2 * i)
      let want = Int(expected[start..<expected.index(start, offsetBy: 2)], radix: 16)!
      worst = max(worst, abs(Int((picture[i] * 255).rounded()) - want))
    }
    #expect(worst <= 2, "the largest difference is \(worst) of 255")
  }

  @Test func aDotAndNothingHaveNoPicture() {
    #expect(SymbolRaster.render([]) == nil)
    #expect(SymbolRaster.render([[Point(3, 3)], [Point(3, 3)]]) == nil)
  }

  @Test func theWeightsAreThoseOfThisNetwork() {
    let net = SymbolNet.bundled
    let picture = SymbolRaster.render([[Point(0, 0), Point(0, 1)]])!
    let p = net.probabilities(picture)
    #expect(p.count == SymbolNet.classCount)
    #expect(abs(p.reduce(0, +) - 1) < 1e-4)
    #expect(SymbolNet(weights: Data(count: 10)) == nil)
  }

  @Test func halfPrecisionNumbersAreReadBack() {
    #expect(SymbolNet.float(fromHalf: 0x3C00) == 1)
    #expect(SymbolNet.float(fromHalf: 0xC000) == -2)
    #expect(SymbolNet.float(fromHalf: 0x0000) == 0)
    #expect(SymbolNet.float(fromHalf: 0x3555) - 0.33325 < 1e-4)
    // The smallest subnormal half, 2^-24.
    #expect(SymbolNet.float(fromHalf: 0x0001) == Float(sign: .plus, exponent: -24, significand: 1))
  }
}
